function renderBar(container, items, formatter, bodyBuilder, onClick){ if(!items.length){container.innerHTML=empty(); return;} const max=Math.max(...items.map(i=>i.value),1), width=760,left=190,right=100,top=16,barH=24,gap=18,usable=width-left-right,height=top+items.length*(barH+gap); const rows=items.map((i,idx)=>{ const y=top+idx*(barH+gap), w=Math.max(8,(i.value/max)*usable); return `<g class="svg-hover" data-title="${esc(i.label)}" data-body="${esc(bodyBuilder(i))}" data-label="${esc(i.label)}"><text x="0" y="${y+15}" fill="#c4c4c4" font-size="12">${esc(i.label)}</text><rect x="${left}" y="${y}" width="${usable}" height="${barH}" rx="10" fill="rgba(255,255,255,.06)"></rect><rect x="${left}" y="${y}" width="${w}" height="${barH}" rx="10" fill="url(#gradB)"></rect><text x="${left+usable+10}" y="${y+15}" fill="#fff" font-size="12">${formatter(i.value)}</text></g>`; }).join(''); container.innerHTML=`<svg viewBox="0 0 ${width} ${height}"><defs><linearGradient id="gradB" x1="0" x2="1"><stop offset="0%" stop-color="#c4a46c"></stop><stop offset="100%" stop-color="#eed7a5"></stop></linearGradient></defs>${rows}</svg>`; bindInteractive(container,onClick); }
function renderColumns(container, items, bodyBuilder){ if(!items.length){container.innerHTML=empty();return;} const width=760,height=310,left=34,right=14,top=18,bottom=42,usableW=width-left-right,usableH=height-top-bottom,max=Math.max(...items.map(i=>i.value),1),step=usableW/items.length,bw=Math.min(48,Math.max(22,step*.58)); let out=`<line x1="${left}" y1="${top+usableH}" x2="${width-right}" y2="${top+usableH}" stroke="rgba(255,255,255,.16)"/>`; items.forEach((i,idx)=>{ const x=left+idx*step+(step-bw)/2,h=Math.max(10,(i.value/max)*usableH),y=top+usableH-h; out += `<g class="svg-hover" data-title="${esc(String(i.label))}" data-body="${esc(bodyBuilder(i))}"><rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="10" fill="url(#gradC)"></rect><text x="${x+bw/2}" y="${y-8}" text-anchor="middle" fill="#fff" font-size="12">${i.value}</text><text x="${x+bw/2}" y="${height-12}" text-anchor="middle" fill="#bcbcbc" font-size="11">${esc(String(i.label))}</text></g>`; }); container.innerHTML=`<svg viewBox="0 0 ${width} ${height}"><defs><linearGradient id="gradC" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#eed7a5"></stop><stop offset="100%" stop-color="#a07d49"></stop></linearGradient></defs>${out}</svg>`; bindInteractive(container); }
function renderLineArea(container, items, mode){ if(!items.length){container.innerHTML=empty('Não há registros com data válida dentro do período selecionado.');return;} const width=760,height=290,left=30,right=16,top=18,bottom=42,usableW=width-left-right,usableH=height-top-bottom,max=Math.max(...items.map(i=>i.value),1),step=items.length>1?usableW/(items.length-1):0; const pts=items.map((i,idx)=>{const x=left+idx*step; const y=top+usableH-(i.value/max)*usableH; return {...i,x,y};}); const area=`${left},${top+usableH} `+pts.map(p=>`${p.x},${p.y}`).join(' ')+` ${width-right},${top+usableH}`; const poly=pts.map(p=>`${p.x},${p.y}`).join(' '); let out=`<polygon points="${area}" fill="url(#gradA)"></polygon><polyline points="${poly}" fill="none" stroke="#c4a46c" stroke-width="3"></polyline><line x1="${left}" y1="${top+usableH}" x2="${width-right}" y2="${top+usableH}" stroke="rgba(255,255,255,.16)"/>`; pts.forEach((p,idx)=>{ const labelShown=(items.length<=8||idx%Math.ceil(items.length/6)===0||idx===items.length-1)?esc(p.label):''; const valText=mode==='revenue'?fmtCurrency.format(p.value):(mode==='cumulative'?fmtCurrency.format(p.value):fmtInt.format(p.value)); out += `<g class="svg-hover" data-title="${esc(p.label)}" data-body="${esc(valText)}"><circle cx="${p.x}" cy="${p.y}" r="5" fill="#eed7a5"></circle><text x="${p.x}" y="${height-12}" text-anchor="middle" fill="#ababab" font-size="10">${labelShown}</text></g>`; }); container.innerHTML=`<svg viewBox="0 0 ${width} ${height}"><defs><linearGradient id="gradA" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(196,164,108,.38)"></stop><stop offset="100%" stop-color="rgba(196,164,108,0)"></stop></linearGradient></defs>${out}</svg>`; bindInteractive(container); }
function renderDonut(container, items){ if(!items.length){container.innerHTML=empty();return;} const colors=['#c4a46c','#eed7a5','#8f7344','#b69a68','#6f5730','#d7c190','#9f9f9f']; const total=sum(items.map(i=>i.value))||1, radius=74,circ=2*Math.PI*radius; let acc=0, arcs='', legend=''; items.forEach((i,idx)=>{ const pct=i.value/total,dash=pct*circ,offset=-acc*circ,color=colors[idx%colors.length]; arcs += `<circle class="svg-hover" data-title="${esc(i.label)}" data-body="${esc(`${i.value} registro(s) • ${fmtPct(pct)}`)}" cx="120" cy="120" r="${radius}" fill="none" stroke="${color}" stroke-width="22" stroke-dasharray="${dash} ${circ-dash}" stroke-dashoffset="${offset}" transform="rotate(-90 120 120)"></circle>`; legend += `<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.06)"><div style="display:flex;gap:10px;align-items:center;min-width:0"><span style="width:10px;height:10px;border-radius:999px;background:${color};display:inline-block"></span><span style="font-size:13px;color:#d4d4d4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(i.label)}</span></div><div style="font-size:12px;color:#fff;font-weight:700;white-space:nowrap">${i.value} • ${fmtPct(pct)}</div></div>`; acc+=pct; }); container.innerHTML=`<div style="display:grid;grid-template-columns:250px 1fr;gap:18px;align-items:center"><svg viewBox="0 0 240 240"><circle cx="120" cy="120" r="${radius}" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="22"></circle>${arcs}<text x="120" y="112" text-anchor="middle" fill="#b7b7b7" font-size="12">Total</text><text x="120" y="138" text-anchor="middle" fill="#fff" font-size="24" font-weight="800">${total}</text></svg><div>${legend}</div></div>`; bindInteractive(container); }
function attachImageFallbacks(scope=document){ scope.querySelectorAll('img[data-fallback]').forEach(img=>{ img.onerror=()=>{ if(img.dataset.failed==='1') return; img.dataset.failed='1'; img.src=img.dataset.fallback; }; }); }
function renderGallery(rows){ const byModel=[...groupBy(rows,r=>r.model).entries()].map(([model,list])=>{ const revenue=sum(list.map(r=>r.salesPrice)); return {model,family:familyFromModel(model),qty:list.length,revenue,avg:revenue/list.length,yearTop:[...groupBy(list,r=>r.modelYear).entries()].sort((a,b)=>b[1].length-a[1].length)[0]?.[0]||'-'}; }).sort((a,b)=>b.revenue-a.revenue||b.qty-a.qty).slice(0,8); els.galleryBadge.textContent=`${byModel.length} modelos em destaque`; if(!byModel.length){ els.modelGallery.innerHTML=empty(); return; } els.modelGallery.innerHTML=byModel.map(m=>{ const fb=fallbackIllustration(m.model); return `<article class="model-card" data-model="${esc(m.model)}"><div class="model-image"><img loading="lazy" src="${photoUrl(m.model) || fb}" data-fallback="${fb}" alt="${esc(m.model)}"><div class="img-fade"></div></div><div class="model-body"><span class="family-pill">${esc(m.family)}</span><div class="model-name" title="${esc(m.model)}">${esc(m.model)}</div><div class="meta-list"><div class="meta-item"><div class="t">Vendas</div><div class="v">${fmtInt.format(m.qty)}</div></div><div class="meta-item"><div class="t">Receita</div><div class="v">${fmtCurrency.format(m.revenue)}</div></div><div class="meta-item"><div class="t">Ticket médio</div><div class="v">${fmtCurrency.format(m.avg)}</div></div><div class="meta-item"><div class="t">Ano dominante</div><div class="v">${esc(m.yearTop)}</div></div></div></div></article>`; }).join(''); attachImageFallbacks(els.modelGallery); els.modelGallery.querySelectorAll('.model-card').forEach(card=>{ card.addEventListener('mouseenter',ev=>showTip(ev,card.dataset.model,'Clique para destacar esse modelo no hero e na leitura executiva.')); card.addEventListener('mousemove',moveTip); card.addEventListener('mouseleave',hideTip); card.addEventListener('click',()=>{ state.showcaseModel=card.dataset.model; updateHero(rows); }); }); }
function updateHero(rows){ if(!rows.length){ const fb=fallbackIllustration('Porsche'); els.heroMedia.style.backgroundImage=`url('${fb}')`; els.heroTitle.textContent='Nenhum dado encontrado para o recorte atual.'; els.heroText.textContent='Ajuste os filtros para visualizar novamente a análise e as imagens dos modelos.'; els.spotlightMain.textContent='Sem destaque'; els.spotlightSub.textContent='Não há registros suficientes no recorte atual.'; els.spotModel.textContent='—'; els.spotModelSub.textContent='—'; els.spotYear.textContent='—'; els.spotYearSub.textContent='—'; els.spotCity.textContent='—'; els.spotCitySub.textContent='—'; return; } const revenueByModel=aggregate(rows,'model','salesPrice').sort((a,b)=>b.value-a.value); const topModel=revenueByModel[0]; const leadModel=state.showcaseModel || (topModel?topModel.label:'Porsche'); const heroFallback=fallbackIllustration(leadModel); const img=new Image(); img.onload=()=>{ els.heroMedia.style.backgroundImage=`url('${photoUrl(leadModel) || heroFallback}')`; }; img.onerror=()=>{ els.heroMedia.style.backgroundImage=`url('${heroFallback}')`; }; img.src=photoUrl(leadModel) || heroFallback; const yearAgg=aggregate(rows,'modelYear',null,true).sort((a,b)=>b.value-a.value||b.label-a.label)[0]; const cityAgg=aggregate(rows,'city','salesPrice').sort((a,b)=>b.value-a.value)[0]; els.heroTitle.textContent=`${leadModel} em destaque na experiência Porsche.`; els.heroText.textContent=`Fotografia real vinculada ao modelo selecionado, quando disponível. A visualização preserva o nome do modelo quando o servidor de fotos não responde.`; els.spotlightMain.textContent=leadModel; els.spotlightSub.textContent=`Receita total do recorte: ${fmtCurrency.format(sum(rows.map(r=>r.salesPrice)))}. Clique em cards de modelo ou barras do ranking para trocar o destaque visual.`; els.spotModel.textContent=topModel?topModel.label:'—'; els.spotModelSub.textContent=topModel?`${fmtCurrency.format(topModel.value)} em receita`:'—'; els.spotYear.textContent=yearAgg?yearAgg.label:'—'; els.spotYearSub.textContent=yearAgg?`${fmtInt.format(yearAgg.value)} venda(s)`:'—'; els.spotCity.textContent=cityAgg?cityAgg.label:'—'; els.spotCitySub.textContent=cityAgg?`${fmtCurrency.format(cityAgg.value)}`:'—'; }
function renderKpis(rows){ const revenue=sum(rows.map(r=>r.salesPrice)), qty=rows.length, avg=qty?revenue/qty:0, models=unique(rows.map(r=>r.model)).length, topCity=aggregate(rows,'city','salesPrice').sort((a,b)=>b.value-a.value)[0]; els.kpiRevenue.textContent=fmtCurrency.format(revenue); els.kpiRevenueSub.textContent=qty?`Receita distribuída em ${qty} venda(s).`:'Sem base no recorte.'; els.kpiSales.textContent=fmtInt.format(qty); els.kpiSalesSub.textContent=qty?'Volume comercial após os filtros.':'Sem registros filtrados.'; els.kpiAvg.textContent=fmtCurrency.format(avg); els.kpiAvgSub.textContent=qty?'Ticket médio por veículo vendido.':'Sem cálculo disponível.'; els.kpiModels.textContent=fmtInt.format(models); els.kpiModelsSub.textContent=qty?'Modelos distintos ativos no recorte.':'Sem mix disponível.'; els.kpiCity.textContent=topCity?topCity.label:'—'; els.kpiCitySub.textContent=topCity?`${fmtCurrency.format(topCity.value)} em faturamento.`:'Nenhuma cidade líder.'; }
function renderEvolution(rows){ const base=datedFiltered(rows); if(!base.length){ els.chartEvolution.innerHTML=empty('Não há registros com data válida dentro do período selecionado.'); return; } const keyFn=state.evoGran==='year'?(r=>r.saleDate.slice(0,4)):(r=>r.saleDate.slice(0,7)); const map=new Map(); base.forEach(r=>{ const k=keyFn(r); if(!map.has(k)) map.set(k,{count:0,revenue:0}); const o=map.get(k); o.count += 1; o.revenue += r.salesPrice; }); let items=[...map.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>({label:state.evoGran==='year'?k:(k.slice(5,7)+'/'+k.slice(0,4)), count:v.count, revenue:v.revenue})); if(state.evoMetric==='cumulative'){ let acc=0; items=items.map(it=>{ acc += it.revenue; return {label:it.label,value:acc}; }); renderLineArea(els.chartEvolution, items, 'cumulative'); return; } renderLineArea(els.chartEvolution, items.map(it=>({label:it.label,value:state.evoMetric==='revenue'?it.revenue:it.count})), state.evoMetric); }
function renderTopModels(rows){ const items=[...groupBy(rows,r=>r.model).entries()].map(([model,list])=>{ const revenue=sum(list.map(r=>r.salesPrice)); return {label:model,value:state.topModelMetric==='revenue'?revenue:list.length,revenue,count:list.length}; }).sort((a,b)=>b.value-a.value||b.revenue-a.revenue).slice(0,10); renderBar(els.chartTopModels, items, state.topModelMetric==='revenue'?fmtCurrencyFn:fmtIntFn, i=>`${fmtInt.format(i.count)} venda(s)<br>${fmtCurrency.format(i.revenue)} de receita`, data=>{ state.showcaseModel=data.label; updateHero(rows); }); }
function renderTopCities(rows){ const items=[...groupBy(rows,r=>r.city).entries()].map(([city,list])=>{ const revenue=sum(list.map(r=>r.salesPrice)); return {label:city,value:state.cityMetric==='revenue'?revenue:list.length,revenue,count:list.length}; }).sort((a,b)=>b.value-a.value||b.revenue-a.revenue).slice(0,10); renderBar(els.chartTopCities, items, state.cityMetric==='revenue'?fmtCurrencyFn:fmtIntFn, i=>`${fmtInt.format(i.count)} venda(s)<br>${fmtCurrency.format(i.revenue)} de receita`); }
function renderStatus(rows){ const items=aggregate(rows,'deliveryStatus',null,true).sort((a,b)=>b.value-a.value).slice(0,8); els.statusBadge.textContent=`${items.length} status`; renderDonut(els.chartStatus, items); }
function renderCityLeaders(rows){ const out=[]; groupBy(rows,r=>r.city).forEach((list,city)=>{ const total=list.length; const ranked=[...groupBy(list,r=>r.model).entries()].map(([model,mList])=>{ const revenue=sum(mList.map(r=>r.salesPrice)); return {model,qty:mList.length,revenue,share:mList.length/total}; }).sort((a,b)=>b.qty-a.qty||b.revenue-a.revenue); if(ranked.length) out.push({city,...ranked[0]}); }); const top=out.sort((a,b)=>b.revenue-a.revenue||b.qty-a.qty).slice(0,12).map(i=>({label:i.city,value:i.revenue,model:i.model,qty:i.qty,share:i.share})); els.cityLeaderBadge.textContent=`${top.length} cidades`; renderBar(els.chartCityLeaders, top, fmtCurrencyFn, i=>`Modelo líder: ${i.model}<br>Vendas: ${i.qty}<br>Receita: ${fmtCurrency.format(i.value)}<br>Share local: ${fmtPct(i.share)}`); }
function renderTopYear(rows){ const base=datedFiltered(rows); const yearItems=aggregate(base,'modelYear',null,true).sort((a,b)=>b.value-a.value||b.label-a.label); if(!yearItems.length){ els.topYearAnswer.textContent='Sem dados válidos no período.'; els.topYearSub.textContent='Ajuste o intervalo para ativar a análise.'; els.periodCoverageBadge.textContent='0 registros'; els.periodPills.innerHTML=''; els.chartModelYear.innerHTML=empty('Sem dados válidos no período.'); return; } const winner=yearItems[0], total=base.length; els.topYearAnswer.textContent=`Ano-modelo ${winner.label} lidera com ${winner.value} venda(s).`; els.topYearSub.textContent=`O ano-modelo ${winner.label} representa ${fmtPct(winner.value/total)} das vendas com data válida no período selecionado.`; els.periodCoverageBadge.textContent=`${total} registro(s) com data válida`; const pills=[]; if(state.dateFrom||state.dateTo) pills.push(`<span class="pill">Período: ${state.dateFrom?fmtDate(state.dateFrom):'Início'} até ${state.dateTo?fmtDate(state.dateTo):'Fim'}</span>`); pills.push(`<span class="pill">Ano campeão: ${winner.label}</span>`); pills.push(`<span class="pill">Participação: ${fmtPct(winner.value/total)}</span>`); els.periodPills.innerHTML=pills.join(''); renderColumns(els.chartModelYear, yearItems.sort((a,b)=>Number(a.label)-Number(b.label)), i=>`${i.value} venda(s) do Ano-modelo ${i.label}`); }
function renderInsights(rows){ if(!rows.length){ els.insightList.innerHTML='<li>Nenhum insight disponível para o recorte atual.</li>'; return; } const cityStats=[...groupBy(rows,r=>r.city).entries()].map(([city,list])=>{ const revenue=sum(list.map(r=>r.salesPrice)), total=list.length; const topModel=[...groupBy(list,r=>r.model).entries()].map(([model,mList])=>({model,qty:mList.length,revenue:sum(mList.map(r=>r.salesPrice))})).sort((a,b)=>b.qty-a.qty||b.revenue-a.revenue)[0]; return {city,revenue,total,avg:revenue/total,topModel}; }).sort((a,b)=>b.total-a.total||b.revenue-a.revenue); const leader=cityStats[0], premium=[...cityStats].sort((a,b)=>b.avg-a.avg)[0], concentrated=[...cityStats].sort((a,b)=>(b.topModel.qty/b.total)-(a.topModel.qty/a.total))[0]; const bullets=[`<li><strong>${esc(leader.city)}</strong> é a principal praça no recorte atual, com <strong>${fmtInt.format(leader.total)} venda(s)</strong> e <strong>${fmtCurrency.format(leader.revenue)} de receita.</strong></li>`,`<li>O modelo líder em <strong>${esc(leader.city)}</strong> é <strong>${esc(leader.topModel.model)}</strong>, reforçando o papel dessa cidade na composição do mix vendido.</li>`,`<li><strong>${esc(premium.city)}</strong> possui o maior ticket médio estimado, em torno de <strong>${fmtCurrency.format(premium.avg)}</strong> por venda.</li>`,`<li>Há maior concentração de um único modelo em <strong>${esc(concentrated.city)}</strong>, onde <strong>${esc(concentrated.topModel.model)}</strong> representa <strong>${fmtPct(concentrated.topModel.qty/concentrated.total)}</strong> do volume local.</li>`]; els.insightList.innerHTML=bullets.join(''); }
function renderTable(rows){ els.tableBadge.textContent=`${rows.length} registros`; els.salesTableBody.innerHTML=rows.length?rows.slice(0,60).map(r=>`<tr><td>${fmtDate(r.saleDate)}</td><td>${esc(r.customer)}</td><td>${esc(r.model)}</td><td>${esc(r.family)}</td><td>${r.modelYear}</td><td>${esc(r.city)} / ${esc(r.state)}</td><td>${fmtCurrency1.format(r.salesPrice)}</td><td>${fmtInt.format(r.mileage)} mi</td><td>${esc(r.payMethod)}</td><td>${esc(r.deliveryStatus)}</td></tr>`).join(''):`<tr><td colspan="10">Nenhum dado encontrado.</td></tr>`; }
function render(){ const rows=baseFiltered(); renderKpis(rows); renderGallery(rows); updateHero(rows); renderEvolution(rows); renderTopModels(rows); renderTopCities(rows); renderStatus(rows); renderCityLeaders(rows); renderTopYear(rows); renderInsights(rows); renderTable(rows); }
initControls(); render();
